*merge in historical cik and ein data from crsp.comphist;
rsubmit;
proc sql; create table /INSERT DATASET/ as select distinct
		a.*, b.hcik,b.hein, b.hchgdt
		from /INSERT DATASET/ as a 
		left join crsp.comphist as b 
		on a.gvkey eq b.gvkey
		and (b.hchgdt) <= (a.datadate) <= (b.hchgenddt)
		order by gvkey, datadate;
		quit;

