*Notes on Merging Exhibit 21 data to other (Compustat) dataset;
***We combine firm-country-year sub counts by: ciknumber, datadate, filedate, country;
***Then, keep firm-country-years with latest filedate;
***Merge to other (e.g., control variable) dataset based on cik;
***Raw data from: 
	country31june2019, assembled by Scott Dyreng (file time stamp: 25JUNE2019 at 9:49 AM Central time);

*Prepare subsidiary data for our use;
data rawdata; set ex21.country31June2019;
run;

*save new permanent file with country names coded to be consistent across Form 5471s and Ex21 (sometimes combined as noted in Excel file);
data ex21.country31June2019_dhlw; set ex21.country31June2019;
country_name_final_ex21 = country;

*combine firm-country-firm years--note: with pointing to common countries (e.g., US minor outlying islands), we need to sum countrycount by firm-country-year;
*we eliminate duplicate firm-country-years arising from multiple filings for the same firm-country-years later;
proc sql;
      create table subs0
      as select distinct CIKNUMBER,IRSNUMBER,NAME,DATADATE,FILEDATE,INCSTATE,HQSTATE,ISO3,IRS,COUNTRY,country_name_final_ex21,TOTALCOUNT,NCOUNTRIES,countrycount,sum(countrycount) as countrycount1
      from ex21.country31June2019_dhlw
	  where not missing(country_name_final_ex21)
      group by ciknumber, datadate,country_name_final_ex21,filedate;quit;run;

*note: can have multiple firm-country-years because of duplicate filedates (likely due to amended 10-K's, etc.);
proc sort data=subs0; by ciknumber datadate country_name_final_ex21 descending totalcount descending filedate;
run;

proc sort data=subs0 out=subs1 dupout=dups nodupkey; by ciknumber datadate country_name_final_ex21;
run;

data subs2;set subs1;
/*use datadates relating to datadates in Compustat*/
datadate_minus_10days=datadate-10;
datadate_ex21 = intnx('month',datadate_minus_10days,1)-1;
format 	datadate_minus_10days YYMMDDN8.;
format 	datadate_ex21 YYMMDDN8.;
run;

*merge in Compustat data using CIKs;
proc sql; create table ex21firm_country_yr as select 
		a.*,b.*,b.datadate as datadate_cpst
		from subs2 as a 
		left join /INSERT CONTROL VARIABLE DATASET NAME/ as b
		on a.ciknumber eq b.(INSERT HISTORICAL CIK, IF AVIALABLE, CIK OTHERWISE, NUMBER FORMATTED)
		and a.datadate_ex21 = b.datadate
		order by gvkey, datadate;
		quit;

*Note: we use EINs to merge the combined Exhibit 21/Compustat, etc. data with IRS data;
	*We match on year and month;
	*We use historical EINs as the primary EIN with Dyreng's Exhibit 21 data to fill-in when missing;
		*historical EINs from CRSP, using earliest available if missing and then ein header file if not available;
